From afe3efde314adeda58bded8a32857c0f54d1d0c9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:09:02 +0100
Subject: [PATCH] plugins/highlightwindow: allow hiding the contents of
 minimized windows

Highlighting a minimized window always showed its full contents, so a
task manager hover could reveal what a hidden window has on screen. A
new D-Bus overload draws minimized windows as a dark silhouette instead.

BUG: 418020
---
 .../highlightwindow/highlightwindow.cpp       | 21 ++++++++++++++++---
 src/plugins/highlightwindow/highlightwindow.h |  5 ++++-
 2 files changed, 22 insertions(+), 4 deletions(-)

diff --git a/src/plugins/highlightwindow/highlightwindow.cpp b/src/plugins/highlightwindow/highlightwindow.cpp
index 63f000c705..4aec8f4b7b 100644
--- a/src/plugins/highlightwindow/highlightwindow.cpp
+++ b/src/plugins/highlightwindow/highlightwindow.cpp
@@ -51,6 +51,11 @@ static bool isHighlightWindow(EffectWindow *window)
 }

 void HighlightWindowEffect::highlightWindows(const QStringList &windows)
+{
+    highlightWindows(windows, false);
+}
+
+void HighlightWindowEffect::highlightWindows(const QStringList &windows, bool hideMinimizedContent)
 {
     QList<EffectWindow *> effectWindows;
     effectWindows.reserve(windows.count());
@@ -61,7 +66,7 @@ void HighlightWindowEffect::highlightWindows(const QStringList &windows)
             effectWindows.append(effectWindow);
         }
     }
-    highlightWindows(effectWindows);
+    highlightWindows(effectWindows, hideMinimizedContent);
 }

 void HighlightWindowEffect::slotWindowAdded(EffectWindow *w)
@@ -120,13 +125,14 @@ void HighlightWindowEffect::finishHighlighting()
     m_highlightedWindows.clear();
 }

-void HighlightWindowEffect::highlightWindows(const QList<KWin::EffectWindow *> &windows)
+void HighlightWindowEffect::highlightWindows(const QList<KWin::EffectWindow *> &windows, bool hideMinimizedContent)
 {
     if (windows.isEmpty()) {
         finishHighlighting();
         return;
     }

+    m_hideMinimizedContent = hideMinimizedContent;
     m_highlightedWindows = windows;
     prepareHighlighting();
 }
@@ -169,6 +175,15 @@ void HighlightWindowEffect::startRevertAnimation(EffectWindow *window)
     }
 }

+bool HighlightWindowEffect::paintWindow(const RenderTarget &renderTarget, const RenderViewport &viewport, EffectWindow *w, int mask, const Region &deviceRegion, WindowPaintData &data)
+{
+    if (m_hideMinimizedContent && w->isMinimized()) {
+        data.setBrightness(0);
+        data.multiplyOpacity(0.5);
+    }
+    return AnimationEffect::paintWindow(renderTarget, viewport, w, mask, deviceRegion, data);
+}
+
 bool HighlightWindowEffect::isHighlighted(EffectWindow *window) const
 {
     return m_highlightedWindows.contains(window);
@@ -192,7 +207,7 @@ bool HighlightWindowEffect::perform(Feature feature, const QVariantList &argumen
     if (arguments.size() != 1) {
         return false;
     }
-    highlightWindows(arguments.first().value<QList<EffectWindow *>>());
+    highlightWindows(arguments.first().value<QList<EffectWindow *>>(), false);
     return true;
 }

diff --git a/src/plugins/highlightwindow/highlightwindow.h b/src/plugins/highlightwindow/highlightwindow.h
index ea0ac71a45..ae758901f4 100644
--- a/src/plugins/highlightwindow/highlightwindow.h
+++ b/src/plugins/highlightwindow/highlightwindow.h
@@ -30,7 +30,9 @@ public:
     bool provides(Feature feature) override;
     bool perform(Feature feature, const QVariantList &arguments) override;
     void reconfigure(ReconfigureFlags flags) override;
+    bool paintWindow(const RenderTarget &renderTarget, const RenderViewport &viewport, EffectWindow *w, int mask, const Region &deviceRegion, WindowPaintData &data) override;
     Q_SCRIPTABLE void highlightWindows(const QStringList &windows);
+    Q_SCRIPTABLE void highlightWindows(const QStringList &windows, bool hideMinimizedContent);

 public Q_SLOTS:
     void slotWindowAdded(KWin::EffectWindow *w);
@@ -45,13 +47,14 @@ private:

     void prepareHighlighting();
     void finishHighlighting();
-    void highlightWindows(const QList<KWin::EffectWindow *> &windows);
+    void highlightWindows(const QList<KWin::EffectWindow *> &windows, bool hideMinimizedContent);

     QList<EffectWindow *> m_highlightedWindows;
     QHash<EffectWindow *, quint64> m_animations;
     QEasingCurve m_easingCurve;
     std::chrono::milliseconds m_fadeDuration;
     float m_ghostOpacity = 0;
+    bool m_hideMinimizedContent = false;
 };

 } // namespace
-- 
